class Solution {
  public int maxArea(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[][] size = new int[m][n];
    int maxSize = 0;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (mat[i][j] == 0) continue;
        size[i][j] =
            1
                + (i > 0 && j > 0
                    ? Math.min(size[i - 1][j - 1], Math.min(size[i - 1][j], size[i][j - 1]))
                    : 0);
        maxSize = Math.max(maxSize, size[i][j]);
      }
    }
    int lo = 0, hi = maxSize;
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (feasible(size, m, n, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo * lo;
  }

  private static boolean feasible(int[][] size, int m, int n, int k) {
    int minR = Integer.MAX_VALUE, maxR = -1, minC = Integer.MAX_VALUE, maxC = -1;
    for (int i = k - 1; i < m; i++) {
      for (int j = k - 1; j < n; j++) {
        if (size[i][j] < k) continue;
        minR = Math.min(minR, i);
        maxR = Math.max(maxR, i);
        minC = Math.min(minC, j);
        maxC = Math.max(maxC, j);
      }
    }
    return maxR >= 0 && (maxR - minR >= k || maxC - minC >= k);
  }
}
